#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testUrlencodeBase64();

void testUrlencodeBase64()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    // Test 1: Simple string
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("hello")), std::string("aGVsbG8")));
    // Test 2: String with space
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("hello world")), std::string("aGVsbG8gd29ybGQ")));
    // Test 3: Short string
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("test")), std::string("dGVzdA")));
    // Test 4: Empty string
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("")), std::string("")));
    // Test 5: Single character
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("a")), std::string("YQ")));
    // Test 6: Two characters
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("ab")), std::string("YWI")));
    // Test 7: Three characters (no padding needed)
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("abc")), std::string("YWJj")));
    // Test 8: Four characters
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("abcd")), std::string("YWJjZA")));
    // Test 9: JSON-like string
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("{\"user\":\"test\"}")), std::string("eyJ1c2VyIjoidGVzdCJ9")));
    // Test 10: String with special characters (urlsafe base64)
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("subjects?_d")), std::string("c3ViamVjdHM_X2Q")));
    // Test 11: Longer string
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("The quick brown fox")), std::string("VGhlIHF1aWNrIGJyb3duIGZveA")));
    // Test 12: Numbers as string
    assertTrue(isEqual(exchange.urlencodeBase64(std::string("123456789")), std::string("MTIzNDU2Nzg5")));
    //
    // add binary tests
    //
    std::any binaryData = exchange.base16ToBinary(std::string("191919191919"));
    assertTrue(isEqual(exchange.urlencodeBase64(binaryData), std::string("GRkZGRkZ")));
}

